(function(){'use strict';
const D=window.GGDashboardData,ICONS=window.GGGoogleIconData||{},$=id=>document.getElementById(id);
const ownIcons={
 grid:'<path d="M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z" fill="none" stroke="currentColor" stroke-width="1.6"/>',
 arrow_right:'<path d="M5 12h14m-5-5 5 5-5 5" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>',
 arrow_up_right:'<path d="M6 18 18 6M6 6h12v12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>',
 trend:'<path d="m3 17 6-6 4 3 8-9m-6 0h6v6" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>',
 chart:'<path d="M4 3v17h17M8 15v-4m5 4V6m5 9V9" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>',
 bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3Zm5 3h4" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>',
 drop:'<path d="M12 3c-2 3-7 8-7 12a7 7 0 0 0 14 0c0-4-5-9-7-12Z" fill="none" stroke="currentColor" stroke-width="1.7"/><path d="M8 15a4 4 0 0 0 4 4" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>',
 close:'<path d="m6 6 12 12M6 18 18 6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>',
 globe:'<circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z" fill="none" stroke="currentColor" stroke-width="1.6"/>'
};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function icon(name){const i=ICONS[name];return `<svg class="icon" viewBox="${i?i.viewBox:'0 0 24 24'}" aria-hidden="true" focusable="false">${i?i.body:ownIcons[name]||ownIcons.grid}</svg>`}
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(node=>{node.innerHTML=icon(node.dataset.icon);node.removeAttribute('data-icon')})}
const num=(v,d=0)=>Number(v).toLocaleString('es-ES',{minimumFractionDigits:d,maximumFractionDigits:d,useGrouping:'always'});
const money=v=>Number.isFinite(v)?num(v,2)+' €':'Sin datos';
const time=()=>new Date(D.snapshot).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'});
const dateLabel=()=>new Date(D.snapshot).toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Madrid'});
const station=id=>D.stations.find(s=>s.id===id);
const KEY='gasgo_service_analytics_v2';
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){}
const state={view:'overview',scope:'all',range:'today',operationFilter:'all',operationQuery:'',page:1,stageFilter:'',alertFilter:'all',following:saved.following&&typeof saved.following==='object'?saved.following:{},density:saved.density==='compact'?'compact':'comfortable'};
const views={overview:['Visión general','grid'],stations:['Estaciones','location_on'],operations:['Sesiones GAS&GO','receipt_long'],alerts:['Incidencias del servicio','bell'],reports:['Rendimiento','chart']};
const eventLabels={session_started:'Sesión GAS&GO iniciada',device_linked:'Dispositivos enlazados',vehicle_identified:'Vehículo identificado',authorization_requested:'Autorización solicitada',authorization_succeeded:'Autorización completada',supply_started:'Suministro iniciado',supply_finished:'Suministro finalizado',invoice_generated:'Factura generada',invoice_download_requested:'Descarga de factura iniciada',link_failed:'Enlace no completado',authorization_failed:'Autorización no completada',session_abandoned:'Sesión cerrada sin finalizar',invoice_failed:'Error al generar la factura'};
const stages=[['session_started','Sesión iniciada'],['device_linked','Enlace'],['vehicle_identified','Identificación'],['authorization_succeeded','Autorización'],['supply_finished','Suministro finalizado'],['invoice_generated','Factura generada']];
const has=(s,name)=>s.events.some(e=>e.name===name),eventAt=(s,name)=>Date.parse(s.events.find(e=>e.name===name)?.at||'');
const percent=(n,d)=>d?n/d*100:0;
const rate=(n,d)=>d?num(percent(n,d),1)+' %':'—';
const seconds=n=>Number.isFinite(n)?num(n/1000,1)+' s':'Sin datos';
const when=iso=>new Date(iso).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Europe/Madrid'});
function selectedStations(){return D.stations.filter(s=>state.scope==='all'||s.id===state.scope)}
const allSessions=[...D.sessions,...D.archivedSessions];
function periodWindow(previous=false){
 const cutoff=Date.parse(D.snapshot),midnight=Date.parse(D.snapshot.slice(0,10)+'T00:00:00+01:00');
 let start=midnight,end=cutoff+1,shift=86400000;
 if(state.range==='yesterday'){start=midnight-86400000;end=midnight}
 if(state.range==='week'){start=midnight-6*86400000;shift=7*86400000}
 return {start:start-(previous?shift:0),end:end-(previous?shift:0)};
}
const dateText=ms=>new Date(ms).toLocaleDateString('es-ES',{day:'numeric',month:'short',timeZone:'Europe/Madrid'});
const rangeName=()=>({today:'Hoy',yesterday:'Ayer',week:'Últimos 7 días'})[state.range];
function windowLabel(previous=false){const w=periodWindow(previous);return dateText(w.start)+(dateText(w.start)===dateText(w.end-1)?'':' – '+dateText(w.end-1))+(state.range==='yesterday'?' · día completo':' · hasta las '+time()+' del último día')}
function inPeriod(previous=false){
 const w=periodWindow(previous);return allSessions.filter(s=>{const started=Date.parse(s.events[0].at);return started>=w.start&&started<w.end}).map(s=>{
  const events=s.events.filter(e=>Date.parse(e.at)<w.end),names=new Set(events.map(e=>e.name));
  const status=names.has('supply_finished')?'completed':names.has('session_abandoned')?'abandoned':names.has('authorization_failed')?'authorization_failed':names.has('link_failed')?'link_failed':names.has('supply_started')?'active':names.has('authorization_succeeded')?'authorized':names.has('device_linked')?'identifying':'linking';
  const clipped=events.length!==s.events.length;
  return {...s,events,status,userId:names.has('vehicle_identified')?s.userId:null,plate:names.has('vehicle_identified')?s.plate:null,quantity:clipped&&!names.has('supply_finished')?null:s.quantity,amount:clipped&&!names.has('supply_finished')?null:s.amount};
 });
}
function scopeSessions(id=state.scope,previous=false){return inPeriod(previous).filter(s=>id==='all'||s.station===id)}
function summary(rows=scopeSessions()){
 const completed=rows.filter(s=>has(s,'supply_finished')),authorized=rows.filter(s=>has(s,'authorization_succeeded')),automatic=authorized.filter(s=>s.method==='A'),users=new Map();
 completed.forEach(s=>{if(s.userId)users.set(s.userId,(users.get(s.userId)||0)+1)});
 const delays=authorized.map(s=>eventAt(s,'authorization_succeeded')-eventAt(s,'session_started')).sort((a,b)=>a-b);
 return {total:rows.length,completed:completed.length,authorized:authorized.length,automatic:automatic.length,amount:completed.reduce((n,s)=>n+s.amount,0),users:users.size,repeatUsers:[...users.values()].filter(n=>n>=2).length,inProgress:rows.filter(s=>['active','identifying','authorized','linking'].includes(s.status)).length,failures:rows.filter(s=>['link_failed','authorization_failed'].includes(s.status)).length,abandoned:rows.filter(s=>s.status==='abandoned').length,invoices:completed.filter(s=>has(s,'invoice_generated')).length,invoiceErrors:completed.filter(s=>has(s,'invoice_failed')).length,downloads:completed.filter(s=>has(s,'invoice_download_requested')).length,averageDelay:delays.length?delays.reduce((a,b)=>a+b,0)/delays.length:NaN,p95Delay:delays.length?delays[Math.ceil(delays.length*.95)-1]:NaN};
}
function alertGroups(scope=state.scope){const groups=[];for(const s of D.stations.filter(s=>scope==='all'||s.id===scope))for(const [type,event,severity,title,code]of [['link','link_failed','warning','Enlaces no completados','LINK_TIMEOUT'],['auth','authorization_failed','critical','Autorizaciones no completadas','AUTH_TIMEOUT'],['invoice','invoice_failed','warning','Facturas con error de generación','PDF_ERROR']]){const affected=scopeSessions(s.id).filter(row=>has(row,event));if(affected.length)groups.push({id:'GASGO-'+s.id+'-'+type+'-'+periodWindow().start+'-'+periodWindow().end,station:s.id,type,event,severity,title,code,affected,count:affected.length,lastAt:affected.flatMap(r=>r.events.filter(e=>e.name===event)).map(e=>e.at).sort().at(-1)})}return groups.sort((a,b)=>(a.severity==='critical'?0:1)-(b.severity==='critical'?0:1)||b.count-a.count)}
function pendingAlerts(){return alertGroups().filter(a=>!state.following[a.id])}
function alerts(){return alertGroups().filter(a=>state.alertFilter==='all'||(state.alertFilter==='following'?!!state.following[a.id]:!state.following[a.id]))}
const statusNames={completed:'Completada',active:'En suministro',identifying:'Identificando',authorized:'Autorizada',linking:'Enlazando',link_failed:'Fallo de enlace',authorization_failed:'No autorizada',abandoned:'Sin finalizar'};
function statusChip(s){return `<span class="status-chip ${s==='completed'?'':s==='active'?'active':['identifying','authorized','linking'].includes(s)?'verifying':'interrupted'}"><i class="status-dot"></i>${statusNames[s]||s}</span>`}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({following:state.following,density:state.density}))}catch(e){toast('No se ha podido guardar la preferencia en este navegador.')}}
function toast(message){clearTimeout(toast.timer);$('toast').textContent=message;$('toast').classList.add('visible');toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3400)}
function renderNav(){const pending=pendingAlerts().length;$('notificationsButton').querySelector('.notification-dot').hidden=pending===0;$('notificationsButton').setAttribute('aria-label','Ver incidencias del servicio pendientes: '+pending);$('navigation').innerHTML=Object.entries(views).map(([key,[name,ic]])=>`<button class="nav-item" data-action="navigate" data-view="${key}" aria-current="${state.view===key?'page':'false'}" title="${name}">${icon(ic)}<span>${name}</span>${key==='alerts'&&pending?`<span class="nav-count">${pending}</span>`:''}</button>`).join('')+'<button class="nav-item" data-action="settings" title="Configuración">'+icon('settings')+'<span>Configuración</span></button>'}
function heading(){const descriptions={overview:'Uso y experiencia de GAS&GO, con indicadores comparables.',stations:'Compara el uso y la experiencia GAS&GO en cada estación.',operations:'Sesiones del servicio: desde el enlace hasta la factura.',alerts:'Problemas de enlace, autorización y generación de facturas.',reports:'Finalización, métodos de autorización, tiempos y experiencia de uso.'};return `<section class="page-heading"><div><p class="eyebrow">${state.scope==='all'?'USO Y EXPERIENCIA DEL SERVICIO':esc(station(state.scope).code)+' · GAS&GO'}</p><h1>${views[state.view][0]}</h1><p class="page-description">Solo actividad GAS&GO · ${descriptions[state.view]}</p></div><div class="heading-controls"><label class="scope-control">${icon('globe')}<span class="visually-hidden">Estación analizada</span><select id="stationScope" aria-label="Estación analizada"><option value="all">Todas las estaciones</option>${D.stations.map(s=>`<option value="${s.id}" ${state.scope===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="scope-control date-control">${icon('calendar_month')}<span class="visually-hidden">Periodo analizado</span><select id="dateRange" aria-label="Periodo analizado">${[['today','Hoy'],['yesterday','Ayer'],['week','Últimos 7 días']].map(([v,l])=>`<option value="${v}" ${state.range===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="button" data-action="export" aria-label="Exportar datos GAS&GO de la vista">${icon('download')} Exportar datos</button></div></section><div class="comparison-context"><span><strong>${rangeName()}</strong> · ${windowLabel()}</span><span>${icon('history')} Comparado con ${windowLabel(true)}</span><button class="definition-link" data-action="period-help">Cómo se compara ${icon('arrow_right')}</button></div>`}

function comparison(current,previous,points=false){if(!Number.isFinite(current)||!Number.isFinite(previous)||(!points&&previous===0))return '<span class="metric-comparison">Sin base anterior comparable</span>';const delta=points?current-previous:(current/previous-1)*100;return `<span class="metric-comparison ${delta<0?'decrease':'increase'}">${delta>0?'+':''}${num(delta,1)} ${points?'pp':'%'} <span>vs. periodo anterior</span></span>`}
function metrics(){const m=summary(),p=summary(scopeSessions(state.scope,true));const info=(key,label)=>`<button class="metric-info" data-action="metric-help" data-metric="${key}" aria-label="Cómo se calcula: ${label}">?</button>`;return `<section class="metric-grid" aria-label="Indicadores del servicio GAS&GO"><article class="metric highlight"><div class="metric-label">Sesiones GAS&GO${info('sessions','sesiones')}</div><div class="metric-value">${num(m.total)}</div><div class="metric-trend">${m.inProgress} en curso · ${m.failures+m.abandoned} cerradas sin completar</div>${comparison(m.total,p.total)}</article><article class="metric"><div class="metric-label">Operaciones completadas${info('completed','completadas')}</div><div class="metric-value">${num(m.completed)}</div><div class="metric-trend"><strong>${rate(m.completed,m.total)}</strong> de las sesiones iniciadas</div>${comparison(m.total?percent(m.completed,m.total):NaN,p.total?percent(p.completed,p.total):NaN,true)}</article><article class="metric"><div class="metric-label">Autorización automática${info('automatic','autorización automática')}</div><div class="metric-value">${rate(m.automatic,m.authorized)}</div><div class="metric-trend">Método A · ${m.automatic} de ${m.authorized} autorizaciones</div>${comparison(m.authorized?percent(m.automatic,m.authorized):NaN,p.authorized?percent(p.automatic,p.authorized):NaN,true)}</article><article class="metric"><div class="metric-label">Importe GAS&GO${info('amount','importe GAS&GO')}</div><div class="metric-value">${money(m.amount)}</div><div class="metric-trend">Solo operaciones completadas · simulado</div>${comparison(m.amount,p.amount)}</article></section>`}

function chartValues(){const w=periodWindow(),rows=scopeSessions().filter(s=>has(s,'supply_finished'));if(state.range!=='week'){const last=(w.end-1-w.start)/3600000,hours=state.range==='today'?[0,2,4,6,8,10,12,last]:[0,4,8,12,16,20,24];return {kind:'cumulative',values:hours.map(h=>rows.filter(s=>eventAt(s,'supply_finished')<=w.start+h*3600000).length),labels:state.range==='today'?['00:00','02:00','04:00','06:00','08:00','10:00','12:00',time()]:['00:00','04:00','08:00','12:00','16:00','20:00','24:00']}}return {kind:'daily',values:Array.from({length:7},(_,i)=>rows.filter(s=>{const t=eventAt(s,'supply_finished');return t>=w.start+i*86400000&&t<w.start+(i+1)*86400000}).length),labels:Array.from({length:7},(_,i)=>dateText(w.start+i*86400000))}}

function chart(){const {values,labels}=chartValues(),max=Math.max(50,Math.ceil(Math.max(...values)/50)*50),w=720,h=150,left=35,right=16,top=10,bottom=24,points=values.map((v,i)=>({x:left+i*(w-left-right)/(values.length-1),y:top+(1-v/max)*(h-top-bottom)})),line=points.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' '),last=points.at(-1);return `<svg class="revenue-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${state.range!=='week'?'Operaciones GAS&GO completadas acumuladas':'Operaciones GAS&GO completadas en los últimos siete días'}: ${values.map((v,i)=>labels[i]+', '+v).join('; ')}">${[0,.5,1].map(f=>{const y=top+(1-f)*(h-top-bottom);return `<line class="chart-grid" x1="${left}" y1="${y}" x2="${w-right}" y2="${y}"/><text class="chart-axis" x="0" y="${y+3}">${num(max*f)}</text>`}).join('')}<path class="chart-fill" d="${line}L${last.x},${h-bottom}L${left},${h-bottom}Z"/><path class="chart-line" d="${line}"/><circle class="chart-point" cx="${last.x}" cy="${last.y}" r="4.5"/>${labels.map((l,i)=>`<text class="chart-axis" text-anchor="${i===0?'start':i===labels.length-1?'end':'middle'}" x="${points[i].x}" y="${h-3}">${l}</text>`).join('')}</svg>`}
function chartPanel(extra='span-8'){const c=chartValues();return `<section class="panel chart-panel ${extra}"><div class="panel-header"><div><h2>Actividad GAS&GO</h2><p>Operaciones completadas · ${c.kind==='cumulative'?'acumulado del día':'por día'}</p></div><span class="period-tag">${rangeName()}</span></div><div class="chart-summary"><strong>${num(summary().completed)}</strong><span>operaciones en el periodo</span></div>${chart()}<div class="chart-footer"><span><i class="legend-dot"></i>${state.scope==='all'?'Toda la red GAS&GO':esc(station(state.scope).name)}</span><button data-action="chart-data">Ver datos ${icon('arrow_right')}</button></div></section>`}

function journeyPanel(){const rows=scopeSessions(),counts=stages.map(([e])=>rows.filter(s=>has(s,e)).length),m=summary(rows);return `<section class="panel journey-panel span-4"><div class="panel-header"><div><h2>Del enlace a la factura</h2><p>Una misma cohorte de ${m.total} sesiones del periodo</p></div>${icon('arrow_right')}</div><ol class="journey-list">${stages.map(([event,label],i)=>`<li><button data-action="stage" data-stage="${event}"><span class="journey-step">${i+1}</span><span class="journey-copy"><strong>${label}</strong><span class="journey-track"><i style="width:${percent(counts[i],m.total)}%"></i></span></span><b>${counts[i]}</b></button></li>`).join('')}</ol><p class="analytics-footnote">${m.inProgress} siguen en curso. Las diferencias entre pasos no equivalen todas a abandono.</p></section>`}
function userPanel(extra='span-4'){const m=summary();return `<section class="panel users-panel ${extra}"><div class="panel-header"><div><h2>Personas que usan GAS&GO</h2><p>Con al menos una operación completada en el periodo</p></div>${icon('directions_car')}</div><div class="user-total">${num(m.users)}<span>usuarios únicos</span></div><div class="repeat-line"><strong>${m.repeatUsers}</strong><div><b>recurrentes en el periodo</b><small>2 o más operaciones en la selección</small></div><span>${rate(m.repeatUsers,m.users)}</span></div><div class="mini-track"><i style="width:${percent(m.repeatUsers,m.users)}%"></i></div><p class="analytics-footnote">Una persona cuenta una sola vez dentro de la selección, aunque visite varias estaciones.</p></section>`}
function stationComparison(){return `<section class="panel span-8"><div class="panel-header"><div><h2>GAS&GO por estación</h2><p>Tasas calculadas sobre las sesiones de cada estación</p></div><button class="panel-link" data-action="navigate" data-view="stations">Comparar ${icon('arrow_right')}</button></div><div class="table-wrap"><table aria-label="Uso de GAS&GO por estación"><thead><tr><th>Estación</th><th>Sesiones</th><th>Completadas</th><th>Finalización</th><th>Método A</th></tr></thead><tbody>${selectedStations().map(s=>{const m=summary(scopeSessions(s.id));return `<tr><td><button class="operation-id" data-action="scope" data-station="${s.id}">${s.name}</button><small class="operation-station">${s.city}</small></td><td>${m.total}</td><td>${m.completed}</td><td><span class="rate-value">${rate(m.completed,m.total)}</span><span class="rate-track"><i style="width:${percent(m.completed,m.total)}%"></i></span></td><td>${rate(m.automatic,m.authorized)}</td></tr>`}).join('')}</tbody></table></div><p class="analytics-footnote">No se conoce la actividad ajena a GAS&GO: no se calcula una cuota sobre el total de la estación.</p></section>`}
function alertCard(a,full=false){return `<button class="${full?'alert-full-card':'alert-card'}" data-action="alert" data-id="${a.id}"><span class="alert-icon ${a.severity}">${icon('warning')}</span><span class="alert-copy"><strong>${esc(a.title)}</strong><small>${station(a.station).name} · ${a.count} ${a.type==='invoice'?(a.count===1?'factura afectada':'facturas afectadas'):(a.count===1?'sesión afectada':'sesiones afectadas')}</small>${full?`<time>${a.code} · Último evento ${when(a.lastAt)}</time>`:''}${state.following[a.id]?'<span class="alert-state">'+icon('check')+' En seguimiento</span>':''}</span>${icon('arrow_right')}</button>`}
function alertsPanel(){const groups=alertGroups();return `<section class="panel alerts-panel span-4"><div class="panel-header"><div><h2>Fricciones del servicio</h2><p>Enlace, autorización y facturas</p></div><span class="count-pill">${pendingAlerts().length} grupos pendientes</span></div><div class="alert-list">${groups.slice(0,3).map(a=>alertCard(a)).join('')||'<p class="page-description">Sin incidencias de muestra en esta selección.</p>'}</div><button class="panel-link" data-action="navigate" data-view="alerts">Ver todos los avisos ${icon('arrow_right')}</button><p class="analytics-footnote">Un aviso puede agrupar varias sesiones afectadas.</p></section>`}
function invoicesPanel(extra='span-4'){const m=summary();return `<section class="panel invoices-panel ${extra}"><div class="panel-header"><div><h2>Entrega de facturas</h2><p>Sobre ${m.completed} operaciones completadas</p></div>${icon('receipt_long')}</div><div class="invoice-ready"><strong>${rate(m.invoices,m.completed)}</strong><span>con factura generada</span></div><div class="invoice-stats"><div><b>${m.invoices}</b><small>generadas</small></div><div><b>${m.invoiceErrors}</b><small>con error</small></div><div><b>${m.downloads}</b><small>descargas iniciadas</small></div></div><button class="panel-link" data-action="invoice-errors">Revisar errores ${icon('arrow_right')}</button><p class="analytics-footnote">Iniciar la descarga no confirma que el archivo se haya guardado en el dispositivo.</p></section>`}
function methodsPanel(extra='span-4'){const rows=scopeSessions().filter(s=>has(s,'authorization_succeeded')),m=summary();return `<section class="panel methods-panel ${extra}"><div class="panel-header"><div><h2>Cómo se autoriza</h2><p>${rows.length} autorizaciones completadas</p></div>${icon('shield')}</div>${[['A','Automática'],['B','Confirmación'],['C','Código alternativo']].map(([method,label])=>{const count=rows.filter(s=>s.method===method).length;return `<div class="method-row"><span class="method-key">${method}</span><div><strong>${label}</strong><div class="method-track"><i style="width:${percent(count,rows.length)}%"></i></div></div><b>${rate(count,rows.length)}</b><small>${count}</small></div>`}).join('')}<div class="method-time"><span>Hasta la autorización</span><strong>${seconds(m.averageDelay)}</strong><small>Media desde el inicio de sesión</small></div></section>`}
function orderedSessions(){return scopeSessions().slice().sort((a,b)=>Date.parse(b.events.at(-1).at)-Date.parse(a.events.at(-1).at))}
function operations(){const q=state.operationQuery.trim().toLocaleLowerCase('es');return orderedSessions().filter(s=>(!state.stageFilter||has(s,state.stageFilter))&&(state.operationFilter==='all'||(state.operationFilter==='invoice_failed'?has(s,'invoice_failed'):s.status===state.operationFilter))&&(!q||[s.id,s.plate,s.product,s.userId,station(s.station).name].join(' ').toLocaleLowerCase('es').includes(q)))}
function tableRows(rows){return rows.map(s=>`<tr><td><button class="operation-id" data-action="operation" data-id="${s.id}">${s.id}</button><small class="operation-station">${station(s.station).name} · ${s.equipment}</small></td><td>${state.range==='week'?dateText(Date.parse(s.events[0].at))+'<small class="operation-station">'+when(s.events[0].at).slice(0,5)+'</small>':when(s.events[0].at).slice(0,5)}</td><td>${s.product}</td><td class="amount-cell">${money(s.amount)}${s.status!=='completed'&&s.amount?'<small class="operation-station">provisional</small>':''}</td><td>${statusChip(s.status)}</td><td>${has(s,'invoice_generated')?'<span class="invoice-label ready">Generada</span>':has(s,'invoice_failed')?'<span class="invoice-label failed">Error</span>':'<span class="invoice-label">—</span>'}</td></tr>`).join('')}
function operationsPanel(){const rows=orderedSessions();return `<section class="panel table-panel span-8"><div class="panel-header"><div><h2>Últimas sesiones GAS&GO</h2><p>Seguimiento de cada recorrido, incluidos los que no finalizan</p></div><button class="panel-link" data-action="navigate" data-view="operations">Ver sesiones ${icon('arrow_right')}</button></div><div class="table-wrap"><table aria-label="Últimas sesiones GAS&GO"><thead><tr><th>Sesión</th><th>Inicio</th><th>Servicio</th><th>Importe</th><th>Estado</th><th>Factura</th></tr></thead><tbody>${tableRows(rows.slice(0,5))}</tbody></table></div><div class="table-footer"><span>5 de ${rows.length} sesiones de la selección</span><span>${rangeName()} · ${windowLabel()}</span></div></section>`}
function overview(){return metrics()+`<div class="bento">${chartPanel()}${journeyPanel()}${stationComparison()}${alertsPanel()}${operationsPanel()}${userPanel()}</div>`}
function stationsView(){return `<div class="section-toolbar"><p class="page-description">${selectedStations().length} estaciones · Solo sesiones registradas por GAS&GO</p><span class="demo-label"><i></i> Datos de demostración</span></div><div class="station-details-grid">${selectedStations().map(s=>{const rows=scopeSessions(s.id),m=summary(rows);return `<section class="panel station-insight-card"><div class="station-detail-title"><div><p class="eyebrow">${s.code}</p><h2>${s.name}</h2><p>${s.city}</p></div><span class="station-pin">${icon('location_on')}</span></div><div class="station-detail-stats"><div><small>Sesiones GAS&GO</small><strong>${m.total}</strong></div><div><small>Finalización</small><strong>${rate(m.completed,m.total)}</strong></div></div><div class="station-analytics-row"><span>Operaciones completadas</span><strong>${m.completed}</strong></div><div class="station-analytics-row"><span>Autorización automática</span><strong>${rate(m.automatic,m.authorized)}</strong></div><div class="station-analytics-row"><span>Usuarios únicos con operación</span><strong>${m.users}</strong></div><div class="station-analytics-row"><span>Hasta autorizar · media</span><strong>${seconds(m.averageDelay)}</strong></div><div class="station-analytics-row"><span>Facturas generadas</span><strong>${m.invoices} / ${m.completed}</strong></div><div class="station-analytics-row"><span>Importe GAS&GO completado</span><strong>${money(m.amount)}</strong></div><button class="panel-link" data-action="station-sessions" data-station="${s.id}">Ver sesiones de GAS&GO ${icon('arrow_right')}</button></section>`}).join('')}</div><p class="analytics-footnote">Los usuarios únicos de distintas estaciones pueden coincidir. El total de la red se calcula sin duplicarlos.</p>`}
function pagedOperations(){const rows=operations();state.page=Math.max(1,Math.min(state.page,Math.ceil(rows.length/20)||1));return rows.slice((state.page-1)*20,state.page*20)}
function pagination(){const rows=operations(),pages=Math.ceil(rows.length/20)||1;return `<span>${rows.length?((state.page-1)*20+1)+'–'+Math.min(state.page*20,rows.length):0} de ${rows.length} sesiones</span><div class="pagination-actions"><button class="button" data-action="operation-page" data-delta="-1" ${state.page===1?'disabled':''}>Anterior</button><span>${state.page} / ${pages}</span><button class="button" data-action="operation-page" data-delta="1" ${state.page===pages?'disabled':''}>Siguiente</button></div>`}
function operationsView(){const tabs=[['all','Todas'],['completed','Completadas'],['active','En suministro'],['identifying','Identificando'],['link_failed','Fallo de enlace'],['authorization_failed','No autorizadas'],['abandoned','Sin finalizar'],['invoice_failed','Factura con error']];return `<div class="section-toolbar"><div class="filter-tabs" aria-label="Estado de sesión">${tabs.map(([id,label])=>`<button class="filter-tab" data-action="operation-filter" data-filter="${id}" aria-pressed="${state.operationFilter===id}">${label}</button>`).join('')}</div><label class="table-search">${icon('search')}<input type="search" id="operationQuery" value="${esc(state.operationQuery)}" placeholder="Sesión, usuario, servicio…" aria-label="Buscar sesiones GAS&GO"></label></div>${state.stageFilter?`<div class="active-stage-filter">Han llegado al paso: <strong>${eventLabels[state.stageFilter]}</strong><button class="button quiet" data-action="clear-stage">Quitar filtro ${icon('close')}</button></div>`:''}<section class="panel standalone-table"><div class="panel-header"><div><h2>Recorridos de GAS&GO</h2><p id="operationCount">${operations().length} sesiones de la selección</p></div><span class="demo-label"><i></i> Datos simulados</span></div><div class="table-wrap"><table aria-label="Registro de sesiones GAS&GO"><thead><tr><th>Sesión / estación</th><th>Inicio</th><th>Servicio</th><th>Importe</th><th>Estado</th><th>Factura</th></tr></thead><tbody id="operationRows">${tableRows(pagedOperations())}</tbody></table></div><div id="operationEmpty" class="empty-state" ${operations().length?'hidden':''}><h3>Sin coincidencias</h3><p>Prueba otra búsqueda o cambia el filtro de estado.</p></div><div class="table-footer" id="operationPagination">${pagination()}</div><p class="analytics-footnote">Importes no finalizados: provisionales. La exportación incluye todos los resultados filtrados, no solo esta página.</p></section>`}
function alertsView(){return `<div class="section-toolbar"><div class="filter-tabs" aria-label="Seguimiento de incidencias">${[['all','Todos los avisos'],['pending','Pendientes'],['following','En seguimiento']].map(([id,label])=>`<button class="filter-tab" data-action="alert-filter" data-filter="${id}" aria-pressed="${state.alertFilter===id}">${label}</button>`).join('')}</div><span class="page-description">${alerts().length} grupos de avisos en la selección</span></div><div class="alert-full-list">${alerts().map(a=>alertCard(a,true)).join('')||`<div class="empty-state">${icon('check_circle')}<h3>Sin avisos con este filtro</h3><p>El seguimiento local no modifica los eventos registrados.</p></div>`}</div>`}
function reportsView(){const m=summary();return `<div class="report-summary"><article class="report-stat"><small>Hasta autorizar · media del periodo</small><strong>${seconds(m.averageDelay)}</strong></article><article class="report-stat"><small>Hasta autorizar · percentil 95 del periodo</small><strong>${seconds(m.p95Delay)}</strong></article><article class="report-stat"><small>Importe medio por operación completada</small><strong>${money(m.amount/m.completed)}</strong></article></div><div class="bento">${chartPanel()}${methodsPanel()}${userPanel()}${invoicesPanel()}<section class="panel span-4"><div class="panel-header"><div><h2>Servicios completados</h2><p>Volumen medido por servicio, sin mezclar unidades</p></div>${icon('local_gas_station')}</div>${['Gasolina 95','Diésel','Electricidad'].map(product=>{const rows=scopeSessions().filter(s=>s.status==='completed'&&s.product===product);return `<div class="service-row"><strong>${product}</strong><b>${rows.length} operaciones</b><span>${num(rows.reduce((n,s)=>n+s.quantity,0),1)} ${product==='Electricidad'?'kWh':'L'}</span></div>`}).join('')}</section><section class="panel span-12"><div class="panel-header"><div><h2>Comparativa de experiencia GAS&GO</h2><p>Los tiempos incluyen enlace, identificación y autorización. Solo sesiones autorizadas.</p></div></div><div class="table-wrap"><table><thead><tr><th>Estación</th><th>Sesiones</th><th>Completadas</th><th>Finalización</th><th>Método A</th><th>Hasta autorizar</th><th>Facturas</th></tr></thead><tbody>${selectedStations().map(s=>{const m=summary(scopeSessions(s.id));return `<tr><td>${s.name}</td><td>${m.total}</td><td>${m.completed}</td><td>${rate(m.completed,m.total)}</td><td>${rate(m.automatic,m.authorized)}</td><td>${seconds(m.averageDelay)}</td><td>${m.invoices} / ${m.completed}</td></tr>`}).join('')}</tbody></table></div></section></div>`}
function render(){const focus=document.activeElement,action=focus?.dataset.action,token=focus?.dataset.period||focus?.dataset.filter,scopeFocused=focus?.id==='stationScope',dateFocused=focus?.id==='dateRange';document.body.dataset.density=state.density;renderNav();$('breadcrumb').textContent=views[state.view][0];$('dashboard').innerHTML=heading()+(navigator.onLine===false?'<div class="offline-strip">Sin conexión. Se muestra el conjunto de demostración incluido, sin nuevas lecturas del servicio.</div>':'')+({overview,stations:stationsView,operations:operationsView,alerts:alertsView,reports:reportsView}[state.view])();hydrate();$('stationScope').addEventListener('change',e=>{state.scope=e.target.value;state.page=1;render()});$('dateRange').addEventListener('change',e=>{state.range=e.target.value;state.page=1;state.stageFilter='';render()});const q=$('operationQuery');if(q)q.addEventListener('input',()=>{state.operationQuery=q.value;state.page=1;const rows=operations();$('operationRows').innerHTML=tableRows(pagedOperations());$('operationPagination').innerHTML=pagination();$('operationCount').textContent=rows.length+' sesiones de la selección';$('operationEmpty').hidden=rows.length>0});if(dateFocused)$('dateRange').focus({preventScroll:true});else if(scopeFocused)$('stationScope').focus({preventScroll:true});else if(['period','operation-filter','alert-filter'].includes(action))document.querySelector(`[data-action="${action}"][data-${action==='period'?'period':'filter'}="${token}"]`)?.focus({preventScroll:true})}
function navigate(view){if(!views[view])return;state.view=view;render();window.scrollTo({top:0,behavior:'instant'});$('main').focus({preventScroll:true})}
let returnFocus=null;
function showDetail(title,eyebrow,body){const dialog=$('detailDialog');if(!dialog.open)returnFocus=document.activeElement;$('detailContent').innerHTML=`<div class="dialog-head"><div><p class="eyebrow">${eyebrow}</p><h2 id="detailTitle">${title}</h2></div><button class="icon-button" data-action="close-detail" aria-label="Cerrar detalle">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.querySelector('button')?.focus()}
function alertDetail(id){const a=alertGroups('all').find(a=>a.id===id);if(!a)return;const explanations={link:'La sesión se inició, pero no se completó el enlace entre la app y el surtidor dentro del tiempo previsto.',auth:'El vehículo llegó al paso de identificación, pero la validación de autorización agotó su tiempo de espera.',invoice:'El suministro finalizó, pero se registró un error al generar su factura.'};showDetail(esc(a.title),a.id.toUpperCase(),`<div class="detail-status ${a.severity}">${icon('warning')}${a.severity==='critical'?'Prioridad alta':'Revisión recomendada'} · ${state.following[id]?'En seguimiento':'Pendiente'}</div><dl class="detail-grid"><div><dt>Estación</dt><dd>${station(a.station).name}</dd></div><div><dt>Sesiones afectadas</dt><dd>${a.count}</dd></div><div><dt>Último evento</dt><dd>${dateText(Date.parse(a.lastAt))} · ${when(a.lastAt)}</dd></div><div><dt>Motivo registrado · demo</dt><dd>${a.code}</dd></div></dl><h3>Qué registra GAS&GO</h3><p>${explanations[a.type]}</p><h3>Sesiones de este aviso</h3><div class="affected-sessions">${a.affected.map(s=>`<button class="operation-id" data-action="operation" data-id="${s.id}">${s.id} ${icon('arrow_right')}</button>`).join('')}</div><div class="detail-note">El seguimiento es una anotación local. No cambia los eventos, no da una sesión por completada ni reintenta la autorización o la factura.</div><div class="dialog-actions"><button class="button ${state.following[id]?'':'primary'}" data-action="follow-alert" data-id="${id}">${icon(state.following[id]?'history':'check')}${state.following[id]?'Volver a pendiente':'Poner en seguimiento'}</button><button class="button" data-action="alert-sessions" data-type="${a.type}" data-station="${a.station}">Ver sesiones</button></div>`)}
function operationDetail(id){const s=inPeriod().find(s=>s.id===id);if(!s)return;const done=has(s,'supply_finished'),identified=has(s,'vehicle_identified');showDetail(s.id,'SESIÓN GAS&GO · '+station(s.station).name.toUpperCase(),`${statusChip(s.status)}<p class="dialog-amount" style="margin-top:22px">${money(s.amount)}</p><p>${done?'Importe de la operación completada':'Importe provisional · no es confirmación de cobro'}</p><dl class="detail-grid"><div><dt>Estación / punto</dt><dd>${station(s.station).name} · ${s.equipment}</dd></div><div><dt>Servicio</dt><dd>${s.product}</dd></div><div><dt>Cantidad registrada</dt><dd>${s.quantity==null?'Sin lectura en este corte':num(s.quantity,2)+' '+s.unit}</dd></div><div><dt>Usuario anonimizado</dt><dd>${s.userId||'Sin identificar'}</dd></div><div><dt>Matrícula de muestra</dt><dd>${identified?esc(s.plate):'Sin identificación validada'}</dd></div><div><dt>Autorización</dt><dd>${has(s,'authorization_succeeded')?s.method==='A'?'Método A · automática':'Método '+s.method:'Sin completar'}</dd></div></dl><h3>Recorrido registrado</h3><ol class="timeline">${s.events.map(e=>`<li>${eventLabels[e.name]}<small>${dateText(Date.parse(e.at))} · ${when(e.at)}${e.code?' · '+e.code:''}</small></li>`).join('')}</ol><div class="detail-note">La descarga de una factura registra la solicitud de descarga; no confirma el guardado del archivo. Todos los eventos de esta sesión son simulados.</div><div class="dialog-actions"><button class="button primary" data-action="export-operation" data-id="${id}">${icon('download')}Exportar sesión CSV</button></div>`)}
function stageDetail(stage){if(!stages.some(([e])=>e===stage))return;const rows=scopeSessions(),reached=rows.filter(s=>has(s,stage)),m=summary(rows);showDetail(eventLabels[stage],'RECORRIDO GAS&GO · '+rangeName().toUpperCase(),`<div class="dialog-amount">${reached.length} <small>de ${rows.length} sesiones</small></div><p>Sesiones de la selección con el evento «${eventLabels[stage]}» registrado.</p><div class="detail-note">${m.inProgress} sesiones de la cohorte siguen en curso. La diferencia con el paso anterior puede incluir espera, incidencias o una salida sin finalizar. No se interpreta automáticamente como abandono.</div><div class="dialog-actions"><button class="button primary" data-action="stage-sessions" data-stage="${stage}">Ver sesiones de este paso ${icon('arrow_right')}</button></div>`)}
function metricHelp(key){const m=summary(),p=summary(scopeSessions(state.scope,true));const defs={sessions:['Sesiones GAS&GO','Número de sesiones iniciadas dentro del periodo y estación seleccionados.',`${m.total} sesiones iniciadas`,`${p.total} sesiones en el periodo anterior`],completed:['Operaciones completadas','Finalización = sesiones con suministro finalizado / sesiones iniciadas. La variación se expresa en puntos porcentuales (pp).',`${m.completed} / ${m.total} = ${rate(m.completed,m.total)}`,`${p.completed} / ${p.total} = ${rate(p.completed,p.total)}`],automatic:['Autorización automática','Método A / todas las autorizaciones completadas. Las solicitudes fallidas quedan fuera del denominador. Variación en puntos porcentuales (pp).',`${m.automatic} / ${m.authorized} = ${rate(m.automatic,m.authorized)}`,`${p.automatic} / ${p.authorized} = ${rate(p.automatic,p.authorized)}`],amount:['Importe GAS&GO','Suma de importes de operaciones completadas. Excluye importes provisionales, actividad ajena a GAS&GO e ingresos incrementales.',money(m.amount),money(p.amount)]};const d=defs[key];if(!d)return;showDetail(d[0],'DEFINICIÓN DEL INDICADOR',`<p>${d[1]}</p><h3>Selección actual</h3><p>${windowLabel()}</p><div class="metric-formula">${d[2]}</div><h3>Periodo anterior equivalente</h3><p>${windowLabel(true)}</p><div class="metric-formula secondary">${d[3]}</div><div class="detail-note">Solo se usan los eventos que ya habían ocurrido en cada corte. Los datos de ambos periodos son simulados y las sesiones en curso se mantienen como tales.</div>`)}
function periodHelp(){showDetail('Cómo se comparan los periodos','MISMA VENTANA TEMPORAL',`<h3>Actual</h3><p>${windowLabel()}</p><h3>Anterior equivalente</h3><p>${windowLabel(true)}</p><p>Hoy se compara con ayer hasta la misma hora. Ayer se compara con el día anterior completo. Los últimos siete días se comparan con la semana previa, recortando su último día a la misma hora.</p><div class="detail-note">Cada cohorte contiene las sesiones iniciadas dentro de su ventana. Los eventos posteriores al corte no se cuentan, aunque ya existan en los datos de demostración. Los cambios de tasas se muestran en puntos porcentuales; los de sesiones e importes, como variación relativa. No implican causalidad ni ahorro.</div>`)}
function settings(){showDetail('Preferencias del panel','ANALÍTICA DEL SERVICIO',`<p>Adapta la densidad de información a tu pantalla. La preferencia se guarda solo en este navegador.</p><form id="settingsForm"><label class="settings-field">Densidad de la vista<select id="density"><option value="comfortable" ${state.density==='comfortable'?'selected':''}>Cómoda</option><option value="compact" ${state.density==='compact'?'selected':''}>Compacta</option></select></label><div class="dialog-actions"><button type="submit" class="button primary">Guardar preferencias</button></div></form><div class="detail-note">Ana Martí · perfil ficticio. El panel analiza GAS&GO; no es una herramienta de gestión física de la estación.</div>`);$('settingsForm').addEventListener('submit',event=>{event.preventDefault();state.density=$('density').value;persist();render();$('detailDialog').close();toast('Preferencia de vista guardada.')})}
function showScope(){showDetail('Qué te cuenta GAS&GO','ALCANCE Y DEFINICIONES',`<p>Uso y experiencia del servicio en una estación o en toda la red. Los datos son simulados, con corte el 9 de noviembre de 2026 a las ${time()} de Madrid.</p><h3>Qué se mide</h3><p>Sesiones iniciadas, enlace, identificación, autorización, suministro finalizado, factura generada y solicitud de descarga. Los pasos se calculan sobre la misma cohorte de sesiones.</p><h3>Usuarios y porcentajes</h3><p>Usuario único: identificador anonimizado con al menos una operación completada en el periodo. Recurrente en el periodo: dos o más operaciones completadas dentro de la selección. Los usuarios de distintas estaciones se deduplican al consultar toda la red.</p><p>Autorización automática: método A sobre todas las autorizaciones completadas. Tiempo hasta autorizar: inicio de sesión hasta autorización completada, solo en sesiones autorizadas. La tasa de finalización incluye las sesiones que todavía están en curso.</p><h3>Lo que no se puede concluir</h3><p>No se conoce la actividad ajena a GAS&GO. No se calcula su cuota sobre el total de la estación, ahorro de tiempo frente al proceso tradicional ni facturación incremental. El importe mostrado solo suma operaciones GAS&GO completadas.</p><div class="detail-note">No se conecta con la app ni con el surtidor actuales. No hay telemetría real ni instrumentación añadida. Antes de conectar datos reales hay que registrar y validar los eventos de cada paso; los días anteriores también contienen sesiones y eventos de demostración.</div>`)}
function showChartData(){const c=chartValues();showDetail('Datos de actividad',state.range!=='week'?'COMPLETADAS ACUMULADAS · '+rangeName().toUpperCase():'COMPLETADAS POR DÍA · '+rangeName().toUpperCase(),`<div class="table-wrap"><table><thead><tr><th>${state.range!=='week'?'Hora':'Fecha'}</th><th>Operaciones GAS&GO completadas</th></tr></thead><tbody>${c.values.map((v,i)=>`<tr><td>${c.labels[i]}</td><td class="amount-cell">${num(v)}</td></tr>`).join('')}</tbody></table></div><p>La serie se calcula con eventos de finalización dentro del periodo. Los registros de otros días también son sesiones de demostración.</p>`)}
function downloadCSV(name,rows){const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"',blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Datos de demostración exportados.')}
function sessionCSV(rows){return [['DEMO · Sesión','Estación','Inicio ISO','Servicio','Estado','Usuario anónimo','Método autorizado','Cantidad','Unidad','Importe EUR','Factura'],...rows.map(s=>[s.id,station(s.station).name,s.events[0].at,s.product,statusNames[s.status],s.userId||'',has(s,'authorization_succeeded')?s.method:'',s.quantity==null?'':num(s.quantity,2),s.unit,s.amount==null?'':num(s.amount,2),has(s,'invoice_generated')?'Generada':has(s,'invoice_failed')?'Error':'No generada'])]}
function exportCurrent(){if(state.view==='operations')return downloadCSV('gasgo-sesiones-demo-'+state.scope+'.csv',sessionCSV(operations()));if(state.view==='alerts')return downloadCSV('gasgo-incidencias-servicio-demo.csv',[['DEMO · Grupo','Estación','Evento','Sesiones afectadas','Seguimiento'],...alerts().map(a=>[a.id,station(a.station).name,eventLabels[a.event],a.count,state.following[a.id]?'En seguimiento':'Pendiente'])]);downloadCSV('gasgo-analitica-'+state.range+'-demo-'+state.scope+'.csv',[['DEMO · Estación','Periodo Madrid','Inicio periodo ISO','Fin periodo ISO (exclusivo)','Sesiones','Completadas','Finalización %','Autorizadas','Método A','Automática %','Usuarios únicos con operación','Recurrentes del día','Tiempo medio hasta autorizar s','Importe completado EUR','Facturas generadas'],...selectedStations().map(s=>{const m=summary(scopeSessions(s.id));return [s.name,windowLabel(),new Date(periodWindow().start).toISOString(),new Date(periodWindow().end).toISOString(),m.total,m.completed,num(percent(m.completed,m.total),1),m.authorized,m.automatic,num(percent(m.automatic,m.authorized),1),m.users,m.repeatUsers,num(m.averageDelay/1000,1),num(m.amount,2),m.invoices]})])}
function openSearch(){returnFocus=document.activeElement;$('commandQuery').value='';renderSearch();$('searchDialog').showModal();$('commandQuery').focus()}
function renderSearch(){const q=$('commandQuery').value.trim().toLocaleLowerCase('es'),sites=D.stations.filter(s=>!q||[s.name,s.city,s.code].join(' ').toLocaleLowerCase('es').includes(q)),sessions=q?inPeriod().filter(s=>[s.id,s.userId,s.plate,s.product].join(' ').toLocaleLowerCase('es').includes(q)).slice(0,5):[],groups=alertGroups('all').filter(a=>!q||[a.id,a.title,station(a.station).name,a.code].join(' ').toLocaleLowerCase('es').includes(q)).slice(0,3);$('commandResults').innerHTML=(sites.length?'<section class="command-results-group"><h3>ESTACIONES · USO GAS&GO</h3>'+sites.map(s=>`<button class="command-result" data-action="search-station" data-station="${s.id}">${icon('location_on')}<span><strong>${s.name}</strong><small>${s.city}</small></span></button>`).join('')+'</section>':'')+(sessions.length?'<section class="command-results-group"><h3>SESIONES GAS&GO</h3>'+sessions.map(s=>`<button class="command-result" data-action="search-operation" data-id="${s.id}">${icon('receipt_long')}<span><strong>${s.id} · ${station(s.station).name}</strong><small>${s.product} · ${statusNames[s.status]}</small></span></button>`).join('')+'</section>':'')+(groups.length?'<section class="command-results-group"><h3>INCIDENCIAS DEL SERVICIO</h3>'+groups.map(a=>`<button class="command-result" data-action="search-alert" data-id="${a.id}">${icon('warning')}<span><strong>${a.title}</strong><small>${station(a.station).name} · ${a.count} ${a.count===1?'sesión':'sesiones'}</small></span></button>`).join('')+'</section>':'');if(!$('commandResults').innerHTML)$('commandResults').innerHTML='<div class="empty-state"><h3>No hay coincidencias</h3><p>Busca Diagonal, un código de evento o un identificador de sesión.</p></div>'}
function openFiltered(filter,scope=state.scope){state.scope=scope;state.page=1;state.operationFilter=filter;state.operationQuery='';state.stageFilter='';if($('detailDialog').open)$('detailDialog').close();navigate('operations')}
document.addEventListener('click',event=>{const t=event.target.closest('[data-action]');if(!t)return;const a=t.dataset.action,id=t.dataset.id;switch(a){case'navigate':if(t.dataset.view==='operations'){state.page=1;state.operationFilter='all';state.operationQuery='';state.stageFilter=''}navigate(t.dataset.view);break;case'scope':state.scope=t.dataset.station;render();break;case'period':state.range=t.dataset.period==='week'?'week':'today';state.page=1;render();break;case'alert':alertDetail(id);break;case'operation':operationDetail(id);break;case'follow-alert':if(state.following[id])delete state.following[id];else state.following[id]=true;persist();render();alertDetail(id);toast('Seguimiento actualizado. Los eventos originales no cambian.');break;case'operation-filter':state.page=1;state.operationFilter=t.dataset.filter;render();break;case'operation-page':state.page+=Number(t.dataset.delta);render();break;case'alert-filter':state.alertFilter=t.dataset.filter;render();break;case'invoice-errors':openFiltered('invoice_failed');break;case'alert-sessions':openFiltered({link:'link_failed',auth:'authorization_failed',invoice:'invoice_failed'}[t.dataset.type],t.dataset.station);break;case'station-sessions':openFiltered('all',t.dataset.station);break;case'stage':stageDetail(t.dataset.stage);break;case'stage-sessions':state.page=1;state.stageFilter=t.dataset.stage;state.operationFilter='all';state.operationQuery='';$('detailDialog').close();navigate('operations');break;case'clear-stage':state.page=1;state.stageFilter='';render();break;case'export':exportCurrent();break;case'export-operation':downloadCSV(id+'-gasgo-demo.csv',sessionCSV(inPeriod().filter(s=>s.id===id)));break;case'chart-data':showChartData();break;case'settings':settings();break;case'metric-help':metricHelp(t.dataset.metric);break;case'period-help':periodHelp();break;case'close-detail':$('detailDialog').close();break;case'search-station':$('searchDialog').close();state.scope=t.dataset.station;navigate('overview');break;case'search-operation':$('searchDialog').close();operationDetail(id);break;case'search-alert':$('searchDialog').close();alertDetail(id);break;}});
$('searchButton').addEventListener('click',openSearch);$('commandQuery').addEventListener('input',renderSearch);$('closeSearch').addEventListener('click',()=>$('searchDialog').close());$('profileButton').addEventListener('click',settings);$('scopeButton').addEventListener('click',showScope);$('notificationsButton').addEventListener('click',()=>{state.alertFilter='pending';navigate('alerts')});
for(const id of ['detailDialog','searchDialog']){$(id).addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})});$(id).addEventListener('click',event=>{if(event.target!==$(id))return;const r=$(id).getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$(id).close()})}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('searchDialog').open&&!$('detailDialog').open)openSearch()}});
window.addEventListener('offline',render);window.addEventListener('online',render);render();
})();
